import React, { useRef } from 'react';
import { Button } from 'primereact/button';
import { Toast } from 'primereact/toast';

export default function Multiple() {
    const toast = useRef(null);

    const showMultiple = () => {
        toast.current.show([
            { className: 'success', summary: 'Success', detail: 'Message Content', life: 3000 },
            { className: 'info', summary: 'Info', detail: 'Message Content', life: 3050 },
            { className: 'warning', summary: 'Warning', detail: 'Message Content', life: 3100 },
            { className: 'error', summary: 'Error', detail: 'Message Content', life: 3150 }
        ]);
    };

    return (
        <div className="">
            <Toast ref={toast} />
            <Button onClick={showMultiple} label="Multiple" className="warning" />
        </div>
    )
}